// for: repete um número conhecido de vezes
for (let i = 0; i < 3; i++) {
  console.log("Repetição número " + i);
}

// while: repete enquanto a condição for verdadeira
let contador = 0;
while (contador < 3) {
  console.log("Contador vale " + contador);
  contador++;
}

// do-while: executa pelo menos uma vez
let tentativa = 0;
do {
  console.log("Tentativa " + tentativa);
  tentativa++;
} while (tentativa < 1);

const idade = 20;

if (idade >= 18) {
  console.log("Maior de idade");
} else if (idade >= 12) {
  console.log("Adolescente");
} else {
  console.log("Criança");
}

// Mesmo resultado do primeiro caso, usando ternário
const status = idade >= 18 ? "Maior de idade" : "Menor de idade";
console.log(status);

const frutas = ["maçã", "banana", "uva"];

// for-of percorre os VALORES do array
for (const fruta of frutas) {
  console.log(fruta);
}

const pessoa = { nome: "Ana", idade: 30 };

// for-in percorre as CHAVES do objeto
for (const chave in pessoa) {
  console.log(chave + ": " + pessoa[chave]);
}

// Declaração de função
function somar(a, b) {
  return a + b;
}

// Expressão de função
const subtrair = function (a, b) {
  return a - b;
};

// Arrow function
const multiplicar = (a, b) => a * b;

console.log(somar(2, 3));       // 5
console.log(subtrair(5, 1));    // 4
console.log(multiplicar(4, 3)); // 12

function saudar(nome = "visitante") {
  console.log("Olá, " + nome + "!");
}

saudar("Maria"); // Olá, Maria!
saudar();        // Olá, visitante!

function calcularTotal(preco, quantidade = 1) {
  return preco * quantidade;
}

console.log(calcularTotal(10)); // 10

const numeros = [1, 2, 3, 4, 5];

const dobrados = numeros.map((n) => n * 2);
console.log(dobrados); // [2, 4, 6, 8, 10]

const pares = numeros.filter((n) => n % 2 === 0);
console.log(pares); // [2, 4]

const soma = numeros.reduce((total, n) => total + n, 0);
console.log(soma); // 15

const nomes = ["Ana", "Bruno", "Carla"];

nomes.forEach((nome, indice) => {
  console.log(indice + ": " + nome);
});
// 0: Ana
// 1: Bruno
// 2: Carla

const pessoa = {
  nome: "Carlos",
  idade: 28,
  cidade: "São Paulo",
  cumprimentar: function () {
    console.log("Oi, eu sou " + this.nome);
  },
};

console.log(pessoa.nome);       // Carlos
console.log(pessoa["idade"]);   // 28
pessoa.cumprimentar();          // Oi, eu sou Carlos

pessoa.idade = 29; // alterando uma propriedade

const carro = {
  marca: "Toyota",
  mostrarMarca: function () {
    console.log(this.marca);
  },
};

carro.mostrarMarca(); // "Toyota" — this é o objeto "carro"

const outraReferencia = carro.mostrarMarca;
// outraReferencia(); // undefined, pois perdeu o vínculo com "carro"

// Desestruturação de array
const coordenadas = [10, 20];
const [x, y] = coordenadas;
console.log(x, y); // 10 20

// Desestruturação de objeto
const usuario = { nome: "Julia", idade: 25 };
const { nome, idade } = usuario;
console.log(nome, idade); // Julia 25

// Renomeando durante a desestruturação
const { nome: nomeUsuario } = usuario;
console.log(nomeUsuario); // Julia

// Spread: espalhando elementos
const parte1 = [1, 2];
const parte2 = [3, 4];
const combinado = [...parte1, ...parte2];
console.log(combinado); // [1, 2, 3, 4]

const original = { a: 1, b: 2 };
const copia = { ...original, c: 3 };
console.log(copia); // { a: 1, b: 2, c: 3 }

// Rest: agrupando argumentos em um array
function somarTudo(...numeros) {
  return numeros.reduce((total, n) => total + n, 0);
}
console.log(somarTudo(1, 2, 3, 4)); // 10

// HTML de exemplo:
