botao.style.backgroundColor = "lightblue";

// HTML de exemplo:
// <button id="botaoContador">Clique em mim</button>
// <p id="resultado">0 cliques</p>

let cliques = 0;
const botao = document.querySelector("#botaoContador");
const resultado = document.querySelector("#resultado");

botao.addEventListener("click", function () {
  cliques++;
  resultado.textContent = cliques + " cliques";
});

const usuario = { nome: "Pedro", idade: 22, ativo: true };

// Convertendo objeto para texto JSON
const textoJson = JSON.stringify(usuario);
console.log(textoJson); // '{"nome":"Pedro","idade":22,"ativo":true}'

// Convertendo texto JSON de volta para objeto
const objetoRecuperado = JSON.parse(textoJson);
console.log(objetoRecuperado.nome); // Pedro

function processarNumero(numero, callback) {
  const resultado = callback(numero);
  console.log("Resultado:", resultado);
}

processarNumero(5, function (n) {
  return n * n;
});
// Resultado: 25

processarNumero(5, (n) => n + 10);
// Resultado: 15

function criarContador() {
  let contagem = 0; // variável "privada", só acessível internamente

  return function () {
    contagem++;
    return contagem;
  };
}

const contador = criarContador();
console.log(contador()); // 1
console.log(contador()); // 2
console.log(contador()); // 3
// "contagem" não pode ser acessada diretamente de fora de criarContador

function esperar(segundos) {
  return new Promise(function (resolve, reject) {
    if (segundos < 0) {
      reject("Tempo inválido");
    } else {
      setTimeout(function () {
        resolve("Esperou " + segundos + " segundos");
      }, segundos * 1000);
    }
  });
}

esperar(1)
  .then((mensagem) => console.log(mensagem))
  .catch((erro) => console.log("Erro:", erro));

async function buscarUsuario(id) {
  try {
    const resposta = await fetch("https://api.exemplo.com/usuarios/" + id);
    const dados = await resposta.json();
    console.log(dados);
    return dados;
  } catch (erro) {
    console.log("Falha ao buscar usuário:", erro);
  }
}

buscarUsuario(1);

class Animal {
  constructor(nome, som) {
    this.nome = nome;
    this.som = som;
  }

  fazerSom() {
    console.log(this.nome + " faz " + this.som);
  }
}

class Cachorro extends Animal {
  constructor(nome) {
    super(nome, "Au au");
  }
}

const rex = new Cachorro("Rex");
rex.fazerSom(); // Rex faz Au au

// arquivo: matematica.js
export function somar(a, b) {
  return a + b;
}

export const PI = 3.14159;

export default function multiplicar(a, b) {
  return a * b;
}

// arquivo: principal.js
import multiplicar, { somar, PI } from "./matematica.js";

console.log(somar(2, 3));      // 5
console.log(PI);                // 3.14159
console.log(multiplicar(2, 5)); // 10

if (0) {
  console.log("Não aparece, pois 0 é falsy");
}

if ("") {
  console.log("Não aparece, pois string vazia é falsy");
}

if ("Olá") {
  console.log("Aparece, pois texto não vazio é truthy");
}

if ([]) {
  console.log("Aparece! Array vazio é truthy, mesmo parecendo vazio");
}

function dividir(a, b) {
  if (b === 0) {
    throw new Error("Não é possível dividir por zero");
  }
  return a / b;
}

try {
  const resultado = dividir(10, 0);
  console.log(resultado);
} catch (erro) {
  console.log("Ocorreu um erro:", erro.message);
} finally {
  console.log("Tentativa de divisão finalizada");
}
